/* styles.css - Core Stylesheet */

/* 1. Global Reset and Variables */
:root {
    /* Default Theme: OLED Dark */
    --color-bg: #121212;
    --color-text: #e0e0e0;
    --color-accent: #00ffcc;
    --color-glass: rgba(30, 30, 30, 0.7);
    --font-primary: 'Inter', sans-serif;
    --transition-speed: 0.3s;
}

/* 2. Glassmorphism Utility */
.glass-panel {
    background: var(--color-glass);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37);
}

/* 3. Base Layout */
body {
    font-family: var(--font-primary);
    background-color: var(--color-bg);
    color: var(--color-text);
    margin: 0;
    padding: 0;
    transition: background-color var(--transition-speed);
}

/* 4. View Management */
.view {
    transition: opacity var(--transition-speed);
}
.hidden {
    display: none !important;
}

/* 5. Reader Canvas Styling (Focal Point) */
#reading-canvas {
    /* Placeholder for RSVP rendering */
    min-height: 400px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3em;
}

/* 6. Theme Overrides (Sepia Warm) */
.theme-sepia {
    --color-bg: #f5e6d8;
    --color-text: #5c4a3e;
    --color-accent: #a0522d;
    --color-glass: rgba(255, 255, 255, 0.8);
}

